insert into membres (societe_id, slug, nom, role, accroche, profil, experiences, formation, competences, ordre) select id, 'sylvain', 'Sylvain BUSCOT', 'Dirigeant', 'Maître d''œuvre inspiré par le monde de l''installation et l''expérience de la gestion de projet.', 'Ingénieur généraliste diplômé de l''ICAM Lille, Sylvain a passé 6 ans comme responsable d''affaire chez SPIE sur des projets d''électricité, puis rejoint SNEF en 2020 pour diriger l''activité Électricité et CVC tertiaire Hauts-de-France. Il fait aujourd''hui le choix de l''entrepreneuriat et accompagne ses clients en maîtrise d''œuvre et bureau d''études, en électricité et CVC.', '[{"d": "2024 · Lille", "t": "Réhabilitation de la Direction régionale des Finances publiques", "desc": "Diagnostic électrique CFO/CFA, bâtiment IGH de 14 000 m²."}, {"d": "2024 · Wasquehal", "t": "Exotec — Construction du siège régional", "desc": "MOE conception et suivi d''exécution, bâtiment mixte 20 000 m²."}, {"d": "2023 · Lille", "t": "Banque de France — Réhabilitation, 75 rue Royale", "desc": "MOE conception et exécution, bâtiment classé ABF."}]'::jsonb, 'Diplômé ICAM Lille — ingénieur généraliste, module énergies, aménagement et construction.', '["Dimensionnement d''installations électriques", "Réglementation NFC 15-100 / 14-100 / 13-100", "Réglementation ERP électricité", "Dialux Evo", "AutoCAD & Revit"]'::jsonb, 0 from societes where slug='buscot' on conflict (societe_id, slug) do nothing;
insert into membres (societe_id, slug, nom, role, accroche, profil, experiences, formation, competences, ordre) select id, 'maxence', 'Maxence CAQUANT', 'Responsable projets Électricité', 'Maître d''œuvre sensible aux enjeux d''efficacité énergétique et de développement durable.', 'Ingénieur généraliste diplômé de l''ICAM en 2013, Maxence a fait son apprentissage en maîtrise d''ouvrage chez GRTgaz, puis un VIE chez Sogea Maroc comme ingénieur travaux. Après une expérience commerciale, il rejoint Ceratec puis Moduo comme chargé d''affaires CFO-CFA pendant cinq ans. En 2025, il rejoint Buscot Energies pour son expertise en MOE et en intégration photovoltaïque.', '[{"d": "2025 · Villeneuve-d''Ascq", "t": "Construction d''une école d''ingénieur", "desc": "MOE conception et exécution, CFO-CFA-PV, ERP 2ᵉ catégorie."}, {"d": "2024 · Loon-Plage", "t": "Plateforme logistique", "desc": "8 cellules d''entrepôt classées ICPE, CFO-CFA."}, {"d": "2023 · Lille", "t": "Réhabilitation lourde de bureaux", "desc": "MOE conception CFO-CFA, diagnostic de l''existant."}]'::jsonb, 'Diplômé ICAM Lille — ingénieur généraliste.', '["Dimensionnement d''installations électriques", "Réglementation NFC 15-100 / 14-100 / 13-100", "Réglementation ERP électricité", "Dialux Evo", "PV Sol (photovoltaïque)", "AutoCAD & Revit"]'::jsonb, 0 from societes where slug='buscot' on conflict (societe_id, slug) do nothing;
insert into membres (societe_id, slug, nom, role, accroche, profil, experiences, formation, competences, ordre) select id, 'duncan', 'Duncan DICK', 'Responsable projets CVC', 'Maître d''œuvre sensible aux enjeux d''efficacité énergétique et de développement durable.', 'Diplômé d''une licence en énergies renouvelables et efficacité énergétique à l''Université de Lille, Duncan a passé 3 ans chez SARL Beitha comme maître d''œuvre CVC sur des projets variés (laboratoires, logements collectifs, hôtellerie, bureaux). Il rejoint Buscot Energies comme responsable projets, sensibilisé aux enjeux de performance et de développement durable.', '[{"d": "2025 · Annezin", "t": "GRTgaz — Réhabilitation du site", "desc": "Réhabilitation énergétique (décret BACS et tertiaire), solution hybride PAC + géothermie, site occupé."}, {"d": "2023 · Chooz", "t": "EDF — Centrale nucléaire", "desc": "Bureaux et laboratoires en zone de protection renforcée (ZPR), amélioration des performances énergétiques."}, {"d": "2022 · Saint-André", "t": "Dalkia — Aménagement du siège régional", "desc": "Entrepôt, cuisine d''entreprise, salle de sport ; distribution fluides apparente."}]'::jsonb, 'Licence pro Énergies renouvelables & efficacité énergétique — Université de Lille.', '["Dimensionnement d''installations CVC - plomberie", "Réglementation ERP", "AutoCAD & Revit"]'::jsonb, 0 from societes where slug='buscot' on conflict (societe_id, slug) do nothing;
insert into membres (societe_id, slug, nom, role, accroche, profil, experiences, formation, competences, ordre) select id, 'charlotte', 'Charlotte LEMERE', 'Assistante de direction', 'Un soutien polyvalent à la direction du groupement PULZ.', 'Assistante de direction du groupement PULZ (Buscot Energies, Therac, Arteix et Gradient) dans le cadre de son BTS Gestion de la PME, Charlotte apporte un soutien polyvalent à la direction, alliant rigueur organisationnelle, sens des priorités et qualités relationnelles. Elle développe des compétences en communication interne et gestion administrative.', '[{"d": "Depuis 2025 · Wambrechies", "t": "PULZ — Assistante de direction", "desc": "Soutien à la direction du groupement et de ses quatre bureaux d''études."}]'::jsonb, 'BTS Gestion de la PME (alternance, 2025-2027) · L1 de psychologie, Université de Lille.', '["Gestion administrative et organisation des dossiers", "Communication interne / externe", "Office 365", "Suivi des agendas, plannings et réunions", "Dossiers de réponse aux appels d''offres"]'::jsonb, 0 from societes where slug='buscot' on conflict (societe_id, slug) do nothing;
insert into membres (societe_id, slug, nom, role, accroche, profil, experiences, formation, competences, ordre) select id, 'florian', 'Florian COLOMAR', 'Directeur général', 'Ingénieur ESITC Caen, maître d''œuvre et fondateur d''ARTEIX.', 'Ingénieur diplômé de l''ESITC Caen (spécialité bâtiments d''habitation, option économie) et titulaire d''un MAE de l''IAE de Caen, Florian a dirigé la conception et la technique chez plusieurs promoteurs (Edouard-Denis, BPD Marignan) avant de fonder ARTEIX. Il pilote la maîtrise d''œuvre conception/réalisation, l''OPC et l''AMO sur des projets d''habitat, tertiaire et logistique dans le Nord.', '[{"d": "Depuis 2021", "t": "ARTEIX Ingénierie — Directeur général", "desc": "MOE conception/réalisation, OPC, AMO. Habitat, résidences séniors, tertiaire, logistique."}, {"d": "2019-2021 · Lille", "t": "Edouard-Denis — Directeur technique immobilier", "desc": "Optimisation et fiabilisation des études et lancements de travaux."}, {"d": "2012-2016 · Douai", "t": "Hexa-Ingénierie — Chef de projet TCE", "desc": "MOE classique TCE, projets à certifications (Qualitel, HQE), 100 k€ à 25 M€."}]'::jsonb, 'Ingénieur ESITC Caen (2011) · MAE, IAE de Caen · DUT Génie civil, IUT de Béthune.', '["Maîtrise d''œuvre conception/réalisation", "OPC & AMO", "Projets à certifications (Qualitel, HQE)", "AutoCAD, Sketchup, Project", "Anglais B2 (TOEIC 825)"]'::jsonb, 0 from societes where slug='arteix' on conflict (societe_id, slug) do nothing;
insert into membres (societe_id, slug, nom, role, accroche, profil, experiences, formation, competences, ordre) select id, 'alexis', 'Alexis RAZIER', 'Chef de projets', 'Chef de projets en maîtrise d''œuvre, spécialisé habitat et tertiaire.', 'Titulaire d''un Master en promotion immobilière (EFAB Lille) et d''un BTS Bâtiment, Alexis a débuté comme assistant conducteur de travaux puis responsable technique en promotion immobilière avant de rejoindre ARTEIX. Il intervient en maîtrise d''œuvre conception/réalisation, OPC et AMO sur des projets d''habitat, résidences séniors, tertiaire et logistique.', '[{"d": "Depuis 2023", "t": "ARTEIX Ingénierie — Chef de projets", "desc": "MOE conception/réalisation, OPC, AMO. Habitat, résidences séniors, tertiaire, logistique."}, {"d": "2020-2023 · Lille", "t": "SOFIM Promotion — Responsable technique", "desc": "Suivi de chantier, OPR, OPL et livraisons de programmes de logements collectifs."}, {"d": "2019-2020 · Lyon", "t": "EAB Bâtiment — Assistant conducteur de travaux", "desc": "Opération de 600 logements : pilotage d''équipe, planning, suivi financier."}]'::jsonb, 'Master Promotion immobilière (EFAB Lille) · Licence Responsable de programme immobilier · BTS Bâtiment.', '["Maîtrise d''œuvre conception/réalisation", "OPC & AMO", "Suivi de chantier et livraisons", "Revit, Sketchup", "Néerlandais bilingue, anglais B2"]'::jsonb, 0 from societes where slug='arteix' on conflict (societe_id, slug) do nothing;
insert into membres (societe_id, slug, nom, role, accroche, profil, experiences, formation, competences, ordre) select id, 'guillaume', 'Guillaume GUENARD', 'Directeur d''exploitation VRD', 'Ingénieur Travaux Publics, plus de 15 ans en ingénierie VRD.', 'Ingénieur Travaux Publics (formation qualifiante niveau I), Guillaume a construit son expertise VRD depuis le poste de dessinateur-projeteur jusqu''à chef de projet, chez plusieurs bureaux d''études du Nord (Hexa Ingénierie, TN Ingénierie, AGECI). Il dirige aujourd''hui l''exploitation de l''ingénierie VRD chez GRADIENT : voirie, réseaux humides et secs, éclairage et espaces verts.', '[{"d": "Depuis 2025 · Wambrechies", "t": "GRADIENT Ingénierie — Directeur d''exploitation VRD", "desc": "Direction de l''ingénierie VRD du groupement."}, {"d": "2022-2025 · Valenciennes", "t": "AGECI Engineering — Chef de projet VRD", "desc": "Conception et suivi de projets VRD."}, {"d": "2019-2021 · Douai", "t": "TN Ingénierie — Chef de projet VRD", "desc": "Conception et coordination d''aménagements VRD."}]'::jsonb, 'Ingénieur Travaux Publics (BAC+5) · Licence pro Travaux Publics · BTS Travaux Publics · BAC STI Génie civil.', '["Voirie & terrassement", "Réseaux humides et secs", "Éclairage public", "Espaces verts", "AutoCAD, Covadis"]'::jsonb, 0 from societes where slug='gradient' on conflict (societe_id, slug) do nothing;
insert into membres (societe_id, slug, nom, role, accroche, profil, experiences, formation, competences, ordre) select id, 'damien', 'Damien CHARLET', 'Directeur général', 'Dirigeant de THERAC, expert thermique, environnement et acoustique.', 'Titulaire d''un Master Commerce et Management des Affaires Internationales et formé à la RE2020 et à Pléiade, Damien a développé l''activité environnementale de Polyexpert en Hauts-de-France avant de diriger THERAC. Il pilote les études thermiques, ACV et acoustiques, les diagnostics PEMD et l''AMO NF Habitat et Prestaterre, sur des projets neufs et de réhabilitation.', '[{"d": "Aujourd''hui", "t": "THERAC — Directeur général", "desc": "Études thermiques, ACV et acoustiques, diagnostics PEMD, AMO NF Habitat et Prestaterre."}, {"d": "2021-2025", "t": "Polyexpert Environnement — Responsable", "desc": "Développement commercial Hauts-de-France et Île-de-France, études thermiques et acoustiques."}]'::jsonb, 'Master Commerce et Management des Affaires Internationales (Lille 1) · Formation RE2020 · Formation Pléiade.', '["Étude thermique & ACV", "Acoustique du bâtiment", "Diagnostic PEMD", "AMO NF Habitat & Prestaterre", "Pléiades, DB trait"]'::jsonb, 0 from societes where slug='therac' on conflict (societe_id, slug) do nothing;
insert into membres (societe_id, slug, nom, role, accroche, profil, experiences, formation, competences, ordre) select id, 'noann', 'Noann CUVELLIER', 'Responsable projet (alternance)', 'Élève ingénieur en génie énergétique, en alternance chez THERAC.', 'Élève ingénieur en génie énergétique à l''IMT Europe Nord (Dunkerque), après deux années de classe préparatoire, Noann réalise son alternance chez THERAC comme responsable projet. Il intervient sur les études thermiques, acoustiques et environnementales du bureau d''études.', '[{"d": "Aujourd''hui", "t": "THERAC — Responsable projet (alternance)", "desc": "Études thermiques, acoustiques et environnementales."}]'::jsonb, 'Ingénieur en génie énergétique (en cours), IMT Europe Nord · Classes préparatoires PT/PTSI, Lycée Gustave Eiffel · Bac mention Très Bien.', '["Études thermiques", "Études acoustiques", "Études environnementales", "Pléiades, Pack Office", "Anglais C1, espagnol B1"]'::jsonb, 0 from societes where slug='therac' on conflict (societe_id, slug) do nothing;
insert into actualites (slug, titre, categorie, date_publication, extrait, contenu, statut) values ('livraison-de-la-rehabilitation-banque-de-france-a-lille', 'Livraison de la réhabilitation Banque de France à Lille', 'Chantier', '2026-01-15', 'Le groupement PULZ a livré la réhabilitation des espaces tertiaires de la succursale de la Banque de France, rue Royale à Lille.', 'Le groupement PULZ est fier d''annoncer la livraison de la réhabilitation et rénovation des espaces tertiaires de la succursale de la Banque de France, située rue Royale à Lille.\n\nBâtiment classé auprès des Architectes des Bâtiments de France et classé ERP, ce projet a demandé une conception soigneusement intégrée aux contraintes architecturales existantes. BUSCOT ENERGIES est intervenu en maîtrise d''œuvre conception et exécution sur les lots électricité et sûreté.\n\nUn grand merci à l''ensemble des intervenants et à la maîtrise d''ouvrage pour leur confiance tout au long de cette opération.', 'publie') on conflict (slug) do nothing;
insert into actualites (slug, titre, categorie, date_publication, extrait, contenu, statut) values ('pulz-renforce-ses-equipes-en-2026', 'PULZ renforce ses équipes en 2026', 'Vie du groupe', '2026-01-08', 'Le groupement poursuit sa croissance et accueille de nouveaux collaborateurs sur l''ensemble de ses bureaux d''études.', 'Pour accompagner le développement de ses activités, le groupement PULZ renforce ses équipes en ce début d''année 2026.\n\nDe nouveaux profils rejoignent nos bureaux d''études BUSCOT ENERGIES, ARTEIX, GRADIENT et THERAC, dans les domaines des fluides, de l''électricité, de la maîtrise d''œuvre, des VRD et de l''environnement.\n\nNous leur souhaitons la bienvenue et nous réjouissons de construire ensemble les projets de demain.', 'publie') on conflict (slug) do nothing;
insert into actualites (slug, titre, categorie, date_publication, extrait, contenu, statut) values ('therac-accompagne-vos-projets-vers-la-re-2020', 'THERAC accompagne vos projets vers la RE 2020', 'Certification', '2025-12-18', 'Notre bureau d''études thermique et environnement vous accompagne dans la conformité à la RE 2020 et les démarches de certification.', 'Face aux exigences croissantes de la réglementation environnementale, THERAC met son expertise au service de vos projets.\n\nCalculs réglementaires RE 2020, simulation thermique dynamique, analyse du cycle de vie, accompagnement aux certifications Prestaterre, Cerqual et NF Habitat : notre équipe couvre l''ensemble des enjeux thermiques et environnementaux du bâtiment.\n\nContactez-nous pour échanger sur votre projet et ses ambitions environnementales.', 'publie') on conflict (slug) do nothing;
insert into actualites (slug, titre, categorie, date_publication, extrait, contenu, statut) values ('extension-des-tribunes-de-roland-garros', 'Extension des tribunes de Roland Garros', 'Chantier', '2025-12-05', 'PULZ intervient sur l''extension des tribunes Est et Ouest du stade Roland Garros, à Paris.', 'Le groupement PULZ est intervenu sur l''extension des tribunes Est et Ouest du stade Roland Garros, permettant d''augmenter la jauge de 1000 personnes.\n\nUn projet d''envergure mêlant contraintes techniques et délais serrés, sur lequel nos équipes ont su apporter leur expertise en maîtrise d''œuvre et en lots techniques.\n\nUne belle référence qui illustre la capacité du groupement à intervenir sur des ouvrages d''exception.', 'publie') on conflict (slug) do nothing;
insert into actualites (slug, titre, categorie, date_publication, extrait, contenu, statut) values ('retour-sur-notre-participation-au-salon-regional-du-batiment', 'Retour sur notre participation au salon régional du bâtiment', 'Événement', '2025-11-20', 'Les équipes PULZ étaient présentes au salon régional du bâtiment pour échanger avec les acteurs de la construction en Hauts-de-France.', 'Le groupement PULZ a participé au salon régional du bâtiment, l''occasion de rencontrer maîtres d''ouvrage, architectes et partenaires de la filière.\n\nCes échanges nourrissent notre approche collaborative de la maîtrise d''œuvre et confortent notre ancrage dans le territoire des Hauts-de-France.\n\nMerci à toutes les personnes rencontrées sur notre stand. À très bientôt pour de nouveaux projets.', 'publie') on conflict (slug) do nothing;
insert into actualites (slug, titre, categorie, date_publication, extrait, contenu, statut) values ('pulz-la-force-du-groupe-et-l-agilite-de-l-individu', 'PULZ, la force du groupe et l''agilité de l''individu', 'Vie du groupe', '2025-11-06', 'Retour sur la philosophie qui anime notre groupement de bureaux d''études indépendants et solidaires.', 'Le groupement PULZ réunit quatre bureaux d''études indépendants — BUSCOT ENERGIES, ARTEIX, GRADIENT et THERAC — autour d''une même exigence.\n\nChaque membre reste maître de son métier ; ensemble, nous couvrons l''intégralité d''une mission de maîtrise d''œuvre, de la conception au suivi de l''exécution.\n\nCette organisation nous permet d''allier la proximité d''une structure à taille humaine et la puissance d''un collectif pluridisciplinaire.', 'publie') on conflict (slug) do nothing;